"""Run today's source worker and restore its private checkpoint on a fresh server."""
import argparse
from contextlib import closing
from datetime import date, timedelta
from hashlib import file_digest, sha256
import json
from pathlib import Path
import subprocess

from psycopg2 import sql
from sync_v3 import queue
from sync_v3.current_worker import acquisition_failed, process, verify_target
from sync_v3.rehearse import isolated_cluster
from sync_v3.replay import install


def inventory(connection):
    """Compare logical rows independently of PostgreSQL's physical placement."""
    totals = {}
    with connection, connection.cursor() as cur:
        cur.execute('SET TRANSACTION READ ONLY')
        cur.execute("""SELECT tablename FROM pg_tables WHERE schemaname='candidate' ORDER BY tablename""")
        tables = [name for name, in cur]
        for name in tables:
            # Hash large payloads directly in PostgreSQL. Only row hashes
            # cross the socket. Preserve multiplicity and ignore physical order.
            row_value = sql.SQL('to_jsonb(t)::text') if name != 'payloads' else sql.SQL(
                "sha256 || ':' || encode(sha256(encoded_json),'hex')")
            cur.execute(sql.SQL("""SELECT encode(sha256(convert_to({},'UTF8')),'hex') AS digest
                                   FROM candidate.{} t ORDER BY digest""").format(row_value, sql.Identifier(name)))
            digest = sha256()
            for row_digest, in cur:
                digest.update(bytes.fromhex(row_digest))
            totals[name] = dict(rows=cur.rowcount, sha256=digest.hexdigest())
        cur.execute("SELECT sequencename,last_value FROM pg_sequences WHERE schemaname='candidate' ORDER BY sequencename")
        totals['sequences'] = dict(cur.fetchall())
        cur.execute("SELECT count(*) FROM candidate.payloads WHERE sha256 <> encode(sha256(encoded_json),'hex')")
        if cur.fetchone() != (0,):
            raise ValueError('Stored MLB response differs from its retained digest')
    return totals


def checkpoint(owner, client_bin, dump):
    subprocess.run([client_bin / 'pg_dump', '-h', owner.info.host, '-U', owner.info.user, '-d', owner.info.dbname,
                    '--format=custom', '--schema=candidate', '--no-owner', '--file', dump], check=True)
    with dump.open('rb') as data:
        return file_digest(data, 'sha256').hexdigest()


def restore(owner, client_bin, dump):
    # isolated_cluster creates an empty namespace and the restricted roles.
    with owner, owner.cursor() as cur:
        cur.execute('DROP SCHEMA candidate RESTRICT')
    subprocess.run([client_bin / 'pg_restore', '-h', owner.info.host, '-U', owner.info.user, '-d', owner.info.dbname,
                    '--single-transaction', '--exit-on-error', '--no-owner', dump], check=True)


def run(day, directory, bindir, client_bin):
    partial = directory / 'current-worker-pending.pgdump'
    complete = directory / 'current-worker.pgdump'
    report = {}
    with isolated_cluster(bindir) as (owner, connect):
        install(owner)
        with closing(connect()) as worker:
            first = process(worker, day, max_jobs=1, profiles=True)
        report['first_batch'] = first
        if acquisition_failed(first) or first['receipts'] != {'received': 1} or not first['jobs_for_date'].get('pending'):
            raise ValueError('Expected one retained receipt and unfinished current work')
        # End the worker session immediately after it commits a claim, before acquisition.
        with closing(connect()) as worker, worker, worker.cursor() as cur:
            cur.execute('SELECT clock_timestamp()')
            abandoned = queue.claim(cur, cur.fetchone()[0], product_date=day, lease=timedelta(seconds=1))
            if abandoned is None:
                raise ValueError('Expected a ready dated job to interrupt')
            job_id, original_token, _ = abandoned
        report['before_restart'] = inventory(owner)
        report['pending_checkpoint_sha256'] = checkpoint(owner, client_bin, partial)

    # Only restore archives generated by this process from its private socket.
    with isolated_cluster(bindir) as (owner, connect):
        restore(owner, client_bin, partial)
        report['after_restart'] = inventory(owner)
        if report['after_restart'] != report['before_restart']:
            raise ValueError('Unfinished acquisition changed during checkpoint recovery')
        batches = []
        for _ in range(16):
            with closing(connect()) as worker:
                batch = process(worker, day, max_jobs=256, profiles=True)
            batches.append(batch)
            if acquisition_failed(batch) or not batch['receipts'] or set(batch['jobs_for_date']) == {'done'}:
                break
        report['resumed_batches'] = batches
        with closing(connect()) as worker, worker, worker.cursor() as cur:
            cur.execute('''SELECT a.outcome, count(f.id) FROM candidate.attempts a
                           LEFT JOIN candidate.fetches f ON f.token=a.token
                           WHERE a.job_id=%s GROUP BY a.claimed_at,a.outcome ORDER BY a.claimed_at''', (job_id,))
            attempts = cur.fetchall()
            if attempts != [('expired', 0), ('done', 1)]:
                raise ValueError(f'Interrupted job {job_id} has unexpected effects: {attempts}')
            cur.execute('SELECT clock_timestamp()')
            try:
                queue.settle(cur, job_id, original_token, cur.fetchone()[0])
            except ValueError as exc:
                if str(exc) != 'Expired or superseded job claim':
                    raise
            else:
                raise ValueError('Abandoned worker could settle the recovered job')
        report['interrupted_job'] = dict(id=job_id, attempts=attempts, stale_settlement_rejected=True)
        report['source'] = inventory(owner)
        report['checkpoint_sha256'] = checkpoint(owner, client_bin, complete)
        report['checkpoint_bytes'] = complete.stat().st_size

    with isolated_cluster(bindir) as (owner, connect):
        restore(owner, client_bin, complete)
        with closing(connect()) as worker:
            verify_target(worker)
        report['restored'] = inventory(owner)
    (directory / 'current-worker.json').write_text(json.dumps(report, sort_keys=True))
    print(json.dumps(dict(day=str(day), source_jobs=report['source']['jobs']['rows'],
                          checkpoint_bytes=report['checkpoint_bytes'], checkpoint_sha256=report['checkpoint_sha256'],
                          jobs_for_date=batch['jobs_for_date'], resumed_batches=len(batches),
                          restored=report['source'] == report['restored'])), flush=True)
    if (report['source'] != report['restored'] or report['source']['core_selections']['rows']
            or acquisition_failed(batch) or set(batch['jobs_for_date']) != {'done'}
            or not batches[0]['receipts'].get('received')):
        raise ValueError('Incomplete private acquisition or checkpoint recovery')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('day', type=date.fromisoformat)
    parser.add_argument('directory', type=Path)
    parser.add_argument('bindir', type=Path)
    parser.add_argument('--client-bin', type=Path)
    args = parser.parse_args()
    run(args.day, args.directory, args.bindir, args.client_bin or args.bindir)
